"use client";

import {
  Children,
  cloneElement,
  isValidElement,
  useRef,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
} from "react";
import { gsap, ScrollTrigger } from "./gsap";
import { SCROLL_BREAKPOINTS } from "./scroll/scroll-breakpoints";
import {
  clampDisableBelow,
  clampOpacityTo,
  clampScaleTo,
  clampStackOffset,
  resolveScrub,
  SCROLL_SCENE_DEFAULTS,
} from "./scroll/scroll-options";
import { useScrollScene, useScrollSceneMode } from "./scroll/use-scroll-scene";
import type { ScrollScrub } from "./scroll/scroll-types";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

/**
 * Pin each item at the top of the viewport. Previous items scale, fade, and
 * optionally translate as the next item arrives. Last item releases with pin spacing.
 */
export type StickyStackProps = {
  children: ReactNode;
  className?: string;
  /** Target scale for outgoing items. Clamped 0.5-1. Default 0.92. */
  scaleTo?: number;
  /** Target opacity for outgoing items. Clamped 0-1. Default 0.45. */
  opacityTo?: number;
  /** Extra translateY in px applied to outgoing items. Clamped 0-120. Default 0. */
  offset?: number;
  /** ScrollTrigger scrub. `true` or lag in seconds 0-2. Default true. */
  scrub?: ScrollScrub;
  /** Collapse to a normal vertical sequence below this width. Default 768. */
  disableBelow?: number;
  /** Development markers and debug attributes. Default false. */
  debug?: boolean;
};

export type StickyStackItemProps = HTMLAttributes<HTMLElement> & {
  children: ReactNode;
};

export function StickyStack({
  children,
  className,
  scaleTo = SCROLL_SCENE_DEFAULTS.scaleTo,
  opacityTo = SCROLL_SCENE_DEFAULTS.opacityTo,
  offset = SCROLL_SCENE_DEFAULTS.offset,
  scrub = SCROLL_SCENE_DEFAULTS.scrub,
  disableBelow = SCROLL_BREAKPOINTS.collapseBelow,
  debug = false,
}: StickyStackProps) {
  const scope = useRef<HTMLDivElement>(null);
  const resolvedScale = clampScaleTo(scaleTo);
  const resolvedOpacity = clampOpacityTo(opacityTo);
  const resolvedOffset = clampStackOffset(offset);
  const resolvedScrub = resolveScrub(scrub);
  const resolvedBreakpoint = clampDisableBelow(disableBelow);
  const mode = useScrollSceneMode(resolvedBreakpoint);

  useScrollScene({
    scope,
    id: "sticky-stack",
    debug,
    disableBelow: resolvedBreakpoint,
    dependencies: [
      resolvedScale,
      resolvedOpacity,
      resolvedOffset,
      resolvedScrub,
      Children.count(children),
    ],
    setup: ({ mode: sceneMode, markers, idPrefix, root }) => {
      if (sceneMode !== "pin") {
        return;
      }
      const items = Array.from(
        root.querySelectorAll<HTMLElement>("[data-sticky-stack-item]"),
      );
      if (items.length === 0) {
        return;
      }

      items.forEach((item, index) => {
        const next = items[index + 1];
        const layer = item.querySelector<HTMLElement>(
          "[data-sticky-stack-layer]",
        );
        const isLast = !next;

        ScrollTrigger.create({
          id: `${idPrefix}-pin-${String(index)}`,
          trigger: item,
          start: "top top",
          endTrigger: next ?? item,
          end: next ? "top top" : "bottom top",
          pin: true,
          pinSpacing: isLast,
          anticipatePin: 1,
          invalidateOnRefresh: true,
          markers,
        });

        if (next && layer) {
          gsap.to(layer, {
            scale: resolvedScale,
            opacity: resolvedOpacity,
            y: resolvedOffset,
            ease: SCROLL_SCENE_DEFAULTS.ease,
            transformOrigin: "center top",
            scrollTrigger: {
              id: `${idPrefix}-scrub-${String(index)}`,
              trigger: next,
              start: "top bottom",
              end: "top top",
              scrub: resolvedScrub,
              invalidateOnRefresh: true,
              markers,
            },
          });
        }
      });
    },
  });

  return (
      <div
        ref={scope}
        className={cn("relative", className)}
        data-sticky-stack=""
        data-scroll-mode={mode}
      >
        {Children.map(children, (child, index) => {
          if (!isValidElement(child)) {
            return child;
          }
          const element = child as ReactElement<StickyStackItemProps>;
          return cloneElement(element, {
            style: {
              ...element.props.style,
              zIndex: `calc(var(--z-sticky) + ${String(index)})`,
            },
          });
        })}
      </div>
  );
}

export function StickyStackItem({
  children,
  className,
  ...props
}: StickyStackItemProps) {
  return (
    <article
      {...props}
      className={cn("relative", className)}
      data-sticky-stack-item=""
    >
      <div data-sticky-stack-layer="" className="h-full w-full">
        {children}
      </div>
    </article>
  );
}

"use client";

import { useRef, type HTMLAttributes, type ReactNode } from "react";
import { gsap } from "./gsap";
import { SCROLL_BREAKPOINTS } from "./scroll/scroll-breakpoints";
import {
  clampDisableBelow,
  horizontalTravel,
  resolveScrub,
  SCROLL_SCENE_DEFAULTS,
} from "./scroll/scroll-options";
import { useScrollScene, useScrollSceneMode } from "./scroll/use-scroll-scene";
import type { ScrollScrub } from "./scroll/scroll-types";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

/**
 * Pin the wrapper and translate the track from measured widths.
 * Mobile uses native overflow swipe. Reduced motion does not pin.
 */
export type HorizontalGalleryProps = {
  children: ReactNode;
  className?: string;
  trackClassName?: string;
  /** ScrollTrigger scrub. `true` or lag in seconds 0-2. Default true. */
  scrub?: ScrollScrub;
  /** Collapse below this width. Default 768. */
  disableBelow?: number;
  /** Development markers and debug attributes. Default false. */
  debug?: boolean;
};

export type HorizontalGalleryItemProps = HTMLAttributes<HTMLElement> & {
  children: ReactNode;
};

export function HorizontalGallery({
  children,
  className,
  trackClassName,
  scrub = SCROLL_SCENE_DEFAULTS.scrub,
  disableBelow = SCROLL_BREAKPOINTS.collapseBelow,
  debug = false,
}: HorizontalGalleryProps) {
  const scope = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const resolvedScrub = resolveScrub(scrub);
  const resolvedBreakpoint = clampDisableBelow(disableBelow);
  const mode = useScrollSceneMode(resolvedBreakpoint);

  useScrollScene({
    scope,
    id: "horizontal-gallery",
    debug,
    disableBelow: resolvedBreakpoint,
    dependencies: [resolvedScrub],
    setup: ({ mode: sceneMode, markers, idPrefix, root }) => {
      const wrapper = root;
      const track = trackRef.current;
      if (!track) {
        return;
      }

      const writeTravel = () => {
        const travel = horizontalTravel(track.scrollWidth, wrapper.clientWidth);
        wrapper.setAttribute("data-horizontal-travel", String(travel));
        return travel;
      };

      writeTravel();

      if (sceneMode !== "pin") {
        gsap.set(track, { x: 0, clearProps: "transform" });
        return;
      }

      gsap.to(track, {
        x: () => -writeTravel(),
        ease: SCROLL_SCENE_DEFAULTS.ease,
        scrollTrigger: {
          id: `${idPrefix}-track`,
          trigger: wrapper,
          pin: true,
          scrub: resolvedScrub,
          anticipatePin: 1,
          invalidateOnRefresh: true,
          start: "top top",
          end: () => `+=${String(writeTravel())}`,
          markers,
        },
      });
    },
  });

  return (
    <div
      ref={scope}
      className={cn(
        "relative w-full max-w-full",
        mode === "pin" && "overflow-hidden",
        mode === "mobile" && "overflow-x-auto overflow-y-hidden",
        mode === "reduced-motion" && "overflow-visible",
        className,
      )}
      data-horizontal-gallery=""
      data-scroll-mode={mode}
    >
      <div
        ref={trackRef}
        className={cn(
          "flex w-max",
          mode === "reduced-motion" && "w-full flex-col",
          trackClassName,
        )}
        data-horizontal-gallery-track=""
      >
        {children}
      </div>
    </div>
  );
}

export function HorizontalGalleryItem({
  children,
  className,
  ...props
}: HorizontalGalleryItemProps) {
  return (
    <div
      {...props}
      className={cn("shrink-0", className)}
      data-horizontal-gallery-item=""
    >
      {children}
    </div>
  );
}

"use client";

import { useMotionValue, type MotionValue } from "motion/react";
import { useRef, useState, type ReactNode, type RefObject } from "react";
import { ScrollTrigger } from "./gsap";
import { SCROLL_BREAKPOINTS } from "./scroll/scroll-breakpoints";
import { clampDisableBelow } from "./scroll/scroll-options";
import { useScrollScene, useScrollSceneMode } from "./scroll/use-scroll-scene";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

export type PinnedStoryVisualContext<T> = {
  activeIndex: number;
  steps: T[];
  frameProgress: MotionValue<number>;
  sceneProgress: MotionValue<number>;
  progressRef: RefObject<number>;
};

export type PinnedStoryStepContext<T> = {
  step: T;
  index: number;
  isActive: boolean;
  steps: T[];
};

/**
 * Pin a visual while document steps drive a discrete active index.
 * Frame progress is a motion value, not React state.
 */
export type PinnedStoryProps<T> = {
  steps: T[];
  renderVisual: (ctx: PinnedStoryVisualContext<T>) => ReactNode;
  renderStep: (ctx: PinnedStoryStepContext<T>) => ReactNode;
  className?: string;
  visualClassName?: string;
  stepsClassName?: string;
  /** Called when the discrete active step changes. */
  onActiveIndexChange?: (index: number) => void;
  /** Called from ScrollTrigger onUpdate. Do not copy this into React state. */
  onFrameProgress?: (ctx: { index: number; progress: number }) => void;
  /** Collapse below this width. Default 768. */
  disableBelow?: number;
  /** Development markers and debug attributes. Default false. */
  debug?: boolean;
};

export function PinnedStory<T>({
  steps,
  renderVisual,
  renderStep,
  className,
  visualClassName,
  stepsClassName,
  onActiveIndexChange,
  onFrameProgress,
  disableBelow = SCROLL_BREAKPOINTS.collapseBelow,
  debug = false,
}: PinnedStoryProps<T>) {
  const scope = useRef<HTMLDivElement>(null);
  const visualRef = useRef<HTMLDivElement>(null);
  const progressRef = useRef(0);
  const activeRef = useRef(0);
  const onActiveRef = useRef(onActiveIndexChange);
  const onProgressRef = useRef(onFrameProgress);
  onActiveRef.current = onActiveIndexChange;
  onProgressRef.current = onFrameProgress;
  const frameProgress = useMotionValue(0);
  const sceneProgress = useMotionValue(0);
  const [activeIndex, setActiveIndex] = useState(0);
  const resolvedBreakpoint = clampDisableBelow(disableBelow);
  const mode = useScrollSceneMode(resolvedBreakpoint);
  const pinned = mode === "pin";

  useScrollScene({
    scope,
    id: "pinned-story",
    debug,
    disableBelow: resolvedBreakpoint,
    dependencies: [steps.length, pinned],
    setup: ({ mode: sceneMode, markers, idPrefix, root }) => {
      const visual = visualRef.current;
      const stepNodes = Array.from(
        root.querySelectorAll<HTMLElement>("[data-pinned-story-step]"),
      );
      if (stepNodes.length === 0) {
        return;
      }

      const setIndex = (index: number) => {
        if (activeRef.current === index) {
          return;
        }
        activeRef.current = index;
        setActiveIndex(index);
        onActiveRef.current?.(index);
      };

      if (sceneMode === "reduced-motion") {
        return;
      }

      if (sceneMode !== "pin" || !visual) {
        stepNodes.forEach((step, index) => {
          ScrollTrigger.create({
            id: `${idPrefix}-step-${String(index)}`,
            trigger: step,
            start: "top center",
            end: "bottom center",
            onToggle: (self) => {
              if (self.isActive) {
                setIndex(index);
              }
            },
            onUpdate: (self) => {
              progressRef.current = self.progress;
              frameProgress.set(self.progress);
              onProgressRef.current?.({ index, progress: self.progress });
            },
            markers,
          });
        });
        return;
      }

      ScrollTrigger.create({
        id: `${idPrefix}-pin`,
        trigger: root,
        start: "top top",
        end: "bottom bottom",
        pin: visual,
        pinSpacing: false,
        anticipatePin: 1,
        invalidateOnRefresh: true,
        markers,
        onUpdate: (self) => {
          sceneProgress.set(self.progress);
        },
      });

      stepNodes.forEach((step, index) => {
        ScrollTrigger.create({
          id: `${idPrefix}-step-${String(index)}`,
          trigger: step,
          start: "top center",
          end: "bottom center",
          onToggle: (self) => {
            if (self.isActive) {
              setIndex(index);
            }
          },
          onUpdate: (self) => {
            progressRef.current = self.progress;
            frameProgress.set(self.progress);
            onProgressRef.current?.({ index, progress: self.progress });
          },
          markers,
        });
      });
    },
  });

  const visualContext: PinnedStoryVisualContext<T> = {
    activeIndex,
    steps,
    frameProgress,
    sceneProgress,
    progressRef,
  };

  if (!pinned) {
    return (
      <div
        ref={scope}
        className={cn("grid gap-10", className)}
        data-pinned-story=""
        data-scroll-mode={mode}
        data-active-index={String(activeIndex)}
      >
        {steps.map((step, index) => (
          <section
            key={index}
            data-pinned-story-step=""
            data-step-index={String(index)}
            className={cn(stepsClassName)}
          >
            <div
              className={cn(visualClassName)}
              data-pinned-story-visual=""
              data-visual-index={String(index)}
            >
              {renderVisual({ ...visualContext, activeIndex: index })}
            </div>
            {renderStep({
              step,
              index,
              isActive: index === activeIndex,
              steps,
            })}
          </section>
        ))}
      </div>
    );
  }

  return (
    <div
      ref={scope}
      className={cn(
        "grid gap-10 md:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] md:items-start",
        className,
      )}
      data-pinned-story=""
      data-scroll-mode={mode}
      data-active-index={String(activeIndex)}
    >
      <div
        ref={visualRef}
        className={cn("relative", visualClassName)}
        data-pinned-story-visual=""
      >
        {renderVisual(visualContext)}
      </div>
      <div className={cn("grid gap-24", stepsClassName)}>
        {steps.map((step, index) => (
          <section
            key={index}
            data-pinned-story-step=""
            data-step-index={String(index)}
          >
            {renderStep({
              step,
              index,
              isActive: index === activeIndex,
              steps,
            })}
          </section>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useEffect, useState, type RefObject } from "react";
import { registerGsap } from "../gsap";
import { useScopedGsap } from "../use-scoped-gsap";
import {
  resolveScrollSceneMode,
  SCROLL_BREAKPOINTS,
} from "./scroll-breakpoints";
import { clampDisableBelow } from "./scroll-options";
import {
  applyScrollDebugAttrs,
  debugMarkerConfig,
  killTriggersByPrefix,
} from "./scroll-debug";
import {
  observeScrollRefresh,
  refreshScrollLayout,
  waitForScrollAssets,
} from "./use-scroll-refresh";
import type { ScrollSceneContext, ScrollSceneMode } from "./scroll-types";

function readViewportWidth() {
  if (typeof window === "undefined") {
    return null;
  }
  return window.innerWidth;
}

export function useScrollSceneMode(disableBelow: number): ScrollSceneMode {
  const reduce = useReducedMotion();
  const breakpoint = clampDisableBelow(disableBelow);
  const [viewportWidth, setViewportWidth] = useState<number | null>(readViewportWidth);

  useEffect(() => {
    const update = () => {
      setViewportWidth(window.innerWidth);
    };
    update();
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("resize", update);
    };
  }, []);

  return resolveScrollSceneMode({
    reduce,
    viewportWidth,
    disableBelow: breakpoint,
  });
}

export function useScrollScene({
  scope,
  dependencies = [],
  disableBelow = SCROLL_BREAKPOINTS.collapseBelow,
  debug = false,
  id,
  setup,
}: {
  scope: RefObject<HTMLElement | null>;
  dependencies?: unknown[];
  disableBelow?: number;
  debug?: boolean;
  id: string;
  setup: (ctx: ScrollSceneContext) => void | (() => void);
}) {
  const breakpoint = clampDisableBelow(disableBelow);
  const mode = useScrollSceneMode(breakpoint);

  useScopedGsap(() => {
    registerGsap();
    const root = scope.current;
    if (!root) {
      return;
    }

    const idPrefix = `cds-${id}`;
    killTriggersByPrefix(idPrefix);
    applyScrollDebugAttrs(root, debug);
    root.setAttribute("data-scroll-mode", mode);

    const ctx: ScrollSceneContext = {
      mode,
      root,
      markers: debugMarkerConfig(debug) && mode === "pin",
      idPrefix,
      refresh: refreshScrollLayout,
    };
    const userCleanup = setup(ctx);

    void waitForScrollAssets(root).then(() => {
      refreshScrollLayout();
    });

    const stopRefresh = observeScrollRefresh(root, () => {
      refreshScrollLayout();
    });

    return () => {
      userCleanup?.();
      stopRefresh();
      killTriggersByPrefix(idPrefix);
    };
  }, scope, [mode, breakpoint, debug, id, ...dependencies]);
}

import { registerGsap, ScrollTrigger } from "../gsap";

function settleImage(image: HTMLImageElement): Promise<void> {
  const decode = () =>
    image.decode ? image.decode().catch(() => undefined) : Promise.resolve();

  if (image.complete) {
    return decode();
  }

  return new Promise((resolve) => {
    const finish = () => {
      void decode().finally(() => resolve());
    };
    image.addEventListener("load", finish, { once: true });
    image.addEventListener("error", () => resolve(), { once: true });
  });
}

export function waitForScrollAssets(root: ParentNode): Promise<void> {
  if (typeof window === "undefined") {
    return Promise.resolve();
  }
  const images = Array.from(root.querySelectorAll("img"));
  const fonts =
    "fonts" in document
      ? document.fonts.ready.catch(() => undefined)
      : Promise.resolve();
  return Promise.all([fonts, ...images.map((image) => settleImage(image))]).then(
    () => undefined,
  );
}

export function refreshScrollLayout() {
  if (typeof window === "undefined") {
    return;
  }
  registerGsap();
  ScrollTrigger.refresh();
}

export function observeScrollRefresh(
  root: Element,
  onChange: () => void,
): () => void {
  if (typeof window === "undefined") {
    return () => undefined;
  }
  const images = Array.from(root.querySelectorAll("img"));
  const listeners: Array<() => void> = [];

  for (const image of images) {
    const handle = () => {
      onChange();
    };
    image.addEventListener("load", handle);
    listeners.push(() => image.removeEventListener("load", handle));
  }

  const fonts = "fonts" in document ? document.fonts : null;
  if (fonts) {
    const handle = () => {
      onChange();
    };
    fonts.addEventListener("loadingdone", handle);
    listeners.push(() => fonts.removeEventListener("loadingdone", handle));
  }

  return () => {
    for (const dispose of listeners) {
      dispose();
    }
  };
}

import { shouldAnimateMotion } from "../motion-policy";
import { clampDisableBelow, SCROLL_SCENE_DEFAULTS } from "./scroll-options";
import type { ScrollSceneMode } from "./scroll-types";

export const SCROLL_BREAKPOINTS = {
  collapseBelow: SCROLL_SCENE_DEFAULTS.disableBelow,
} as const;

export function scrollMatchMedia(disableBelow: number) {
  const breakpoint = clampDisableBelow(disableBelow);
  const mobileMax = Math.max(0, breakpoint - 1);
  return {
    isDesktop: `(min-width: ${String(breakpoint)}px)`,
    isMobile: `(max-width: ${String(mobileMax)}px)`,
    reduceMotion: "(prefers-reduced-motion: reduce)",
  };
}

export function resolveScrollSceneMode(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): ScrollSceneMode {
  if (!shouldAnimateMotion(options.reduce)) {
    return "reduced-motion";
  }
  const breakpoint = clampDisableBelow(
    options.disableBelow ?? SCROLL_BREAKPOINTS.collapseBelow,
  );
  if (
    breakpoint > 0 &&
    options.viewportWidth != null &&
    options.viewportWidth < breakpoint
  ) {
    return "mobile";
  }
  return "pin";
}

export function shouldPinScrollScene(mode: ScrollSceneMode): boolean {
  return mode === "pin";
}

import { registerGsap, ScrollTrigger } from "../gsap";

export const SCROLL_DEBUG_ATTR = "data-cds-scroll-debug";

export function debugMarkerConfig(enabled: boolean): boolean {
  return enabled;
}

export function countScrollTriggers(prefix?: string): number {
  if (typeof window === "undefined") {
    return 0;
  }
  registerGsap();
  const all = ScrollTrigger.getAll();
  if (!prefix) {
    return all.length;
  }
  return all.filter((trigger) => {
    const id = trigger.vars.id;
    return typeof id === "string" && id.startsWith(prefix);
  }).length;
}

export function killTriggersByPrefix(prefix: string) {
  if (typeof window === "undefined") {
    return;
  }
  registerGsap();
  for (const trigger of ScrollTrigger.getAll()) {
    const id = trigger.vars.id;
    if (typeof id === "string" && id.startsWith(prefix)) {
      trigger.kill(true);
    }
  }
}

export function applyScrollDebugAttrs(root: Element, enabled: boolean) {
  if (enabled) {
    root.setAttribute(SCROLL_DEBUG_ATTR, "true");
    return;
  }
  root.removeAttribute(SCROLL_DEBUG_ATTR);
}

export type ScrollSceneMode = "pin" | "mobile" | "reduced-motion";

export type ScrollScrub = boolean | number;

export type ScrollSceneContext = {
  mode: ScrollSceneMode;
  root: HTMLElement;
  markers: boolean;
  idPrefix: string;
  refresh: () => void;
};

import { clamp } from "../clamp";
import type { ScrollScrub } from "./scroll-types";

export const SCROLL_SCRUB_EASE = "none" as const;

export const SCROLL_SCENE_DEFAULTS = {
  scaleTo: 0.92,
  scaleToMin: 0.5,
  scaleToMax: 1,
  opacityTo: 0.45,
  opacityToMin: 0,
  opacityToMax: 1,
  offset: 0,
  offsetMin: 0,
  offsetMax: 120,
  scrub: true as ScrollScrub,
  scrubLagMax: 2,
  disableBelow: 768,
  disableBelowMin: 0,
  disableBelowMax: 4096,
  ease: SCROLL_SCRUB_EASE,
};

export function clampScaleTo(value: number): number {
  return clamp(
    value,
    SCROLL_SCENE_DEFAULTS.scaleToMin,
    SCROLL_SCENE_DEFAULTS.scaleToMax,
  );
}

export function clampOpacityTo(value: number): number {
  return clamp(
    value,
    SCROLL_SCENE_DEFAULTS.opacityToMin,
    SCROLL_SCENE_DEFAULTS.opacityToMax,
  );
}

export function clampStackOffset(value: number): number {
  return clamp(
    value,
    SCROLL_SCENE_DEFAULTS.offsetMin,
    SCROLL_SCENE_DEFAULTS.offsetMax,
  );
}

export function clampDisableBelow(value: number): number {
  return clamp(
    Math.round(value),
    SCROLL_SCENE_DEFAULTS.disableBelowMin,
    SCROLL_SCENE_DEFAULTS.disableBelowMax,
  );
}

export function resolveScrub(value: ScrollScrub | undefined): ScrollScrub {
  if (value == null) {
    return SCROLL_SCENE_DEFAULTS.scrub;
  }
  if (typeof value === "boolean") {
    return value;
  }
  if (!Number.isFinite(value)) {
    return SCROLL_SCENE_DEFAULTS.scrub;
  }
  return clamp(value, 0, SCROLL_SCENE_DEFAULTS.scrubLagMax);
}

export function horizontalTravel(
  trackWidth: number,
  viewportWidth: number,
): number {
  const track = Number.isFinite(trackWidth) ? Math.max(0, trackWidth) : 0;
  const viewport = Number.isFinite(viewportWidth)
    ? Math.max(0, viewportWidth)
    : 0;
  return Math.max(0, track - viewport);
}

"use client";

import { gsap } from "gsap";
import { CustomEase } from "gsap/CustomEase";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";

let registered = false;
const plugins = [ScrollTrigger, useGSAP, CustomEase];

export function registerGsap() {
  if (registered || typeof window === "undefined") {
    return;
  }
  gsap.registerPlugin(...plugins);
  registered = true;
}

export function reducedMotionMatchMedia() {
  return gsap.matchMedia();
}

export { CustomEase, gsap, ScrollTrigger, useGSAP };

"use client";

import { useGSAP } from "@gsap/react";
import type { RefObject } from "react";
import { registerGsap } from "./gsap";

type Scope = RefObject<Element | null>;

/**
 * Scoped GSAP setup with automatic revert on unmount and on dependency change.
 */
export function useScopedGsap(
  callback: () => void | (() => void),
  scope: Scope,
  dependencies: unknown[] = [],
) {
  registerGsap();
  useGSAP(callback, { scope, dependencies, revertOnUpdate: true });
}

export const MOTION_DEFAULTS = {
  staggerInterval: 0.08,
  staggerDelay: 0,
  staggerAmount: 0.3,
  staggerOnce: true,
  staggerY: 16,
  parallaxSpeed: 0.2,
  parallaxSpeedMin: 0,
  parallaxSpeedMax: 0.45,
  parallaxRangePx: 72,
  magneticStrength: 0.35,
  magneticStrengthMin: 0,
  magneticStrengthMax: 1,
  magneticMaxOffset: 16,
  magneticMaxOffsetMin: 0,
  magneticMaxOffsetMax: 32,
  imageScale: 1,
  imageScaleMin: 1,
  imageScaleMax: 1.08,
  imageRevealY: 24,
  ease: [0.16, 1, 0.3, 1] as const,
  duration: 0.55,
};

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function clampParallaxSpeed(speed: number): number {
  return clamp(
    speed,
    MOTION_DEFAULTS.parallaxSpeedMin,
    MOTION_DEFAULTS.parallaxSpeedMax,
  );
}

export function clampMagneticStrength(strength: number): number {
  return clamp(
    strength,
    MOTION_DEFAULTS.magneticStrengthMin,
    MOTION_DEFAULTS.magneticStrengthMax,
  );
}

export function clampMagneticOffset(offset: number): number {
  return clamp(
    offset,
    MOTION_DEFAULTS.magneticMaxOffsetMin,
    MOTION_DEFAULTS.magneticMaxOffsetMax,
  );
}

export function clampImageScale(scale: number): number {
  return clamp(
    scale,
    MOTION_DEFAULTS.imageScaleMin,
    MOTION_DEFAULTS.imageScaleMax,
  );
}

export function clampStaggerInterval(interval: number): number {
  return clamp(interval, 0, 1);
}

export function parallaxTravelPx(speed: number): number {
  return clampParallaxSpeed(speed) * MOTION_DEFAULTS.parallaxRangePx;
}

export const FINE_POINTER_QUERY = "(pointer: fine) and (hover: hover)";

export function shouldAnimateMotion(
  reduce: boolean | null | undefined,
): boolean {
  return !reduce;
}

export function shouldEnableParallax(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (
    options.disableBelow != null &&
    options.viewportWidth != null &&
    options.viewportWidth < options.disableBelow
  ) {
    return false;
  }
  return true;
}

export function shouldEnableMagnetic(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (!options.finePointer) {
    return false;
  }
  if (
    options.pointerType &&
    options.pointerType !== "mouse" &&
    options.pointerType !== "pen"
  ) {
    return false;
  }
  return true;
}

export function shouldEnablePointerAccent(options: {
  enabled: boolean;
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!options.enabled) {
    return false;
  }
  return shouldEnableMagnetic({
    reduce: options.reduce,
    finePointer: options.finePointer,
    pointerType: options.pointerType,
  });
}
